from html.parser import HTMLParser
from pathlib import Path
class Links(HTMLParser):
 def __init__(self):
  super().__init__(); self.url=None; self.label=[]
 def handle_starttag(self,t,a):
  if t=='a': self.url=dict(a).get('href'); self.label=[]
 def handle_data(self,s):
  if self.url: self.label.append(s)
 def handle_endtag(self,t):
  if t=='a' and self.url:
   label=' '.join(' '.join(self.label).split())
   if any(k in (label+' '+self.url).lower() for k in ['extraction','export','invoice','automation']): print(label, self.url)
   self.url=None
Links().feed(Path('products/services/invoice-export-qa-alternative/raw/dext-canada.html').read_text())
